def update_price(product_id, new_price):
    db.execute("UPDATE product SET price=%s WHERE id=%s", new_price, product_id)
    cache.delete(f"product:{product_id}")  # invalidation explicite, pas seulement un TTL

def get_price(product_id):
    cached = cache.get(f"product:{product_id}")
    return cached if cached else db.fetch_price(product_id)

